+  faccessat;
+  fopen;
+  fstatat;
+  lstat;
+  mkdir;
+  mkdirat;
+  mkostempsat;
+  mkstemp;
+  open;
+  openat;
+  opendir;
+  pathconf;
+  realpath;
+  rename;
+  rmdir;
+  scandir;
+  scandirat;
+  select;
+  stat;
+  statfs;
+  sysctl;
+  sysctlbyname;
+  unlink;
